-- Ticket Booking System Complete Schema and Reseed Data
PRAGMA foreign_keys = OFF;

DROP TABLE IF EXISTS users;
CREATE TABLE users (
    user_id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    phone TEXT,
    role TEXT NOT NULL DEFAULT 'CUSTOMER' CHECK (role IN ('CUSTOMER', 'ORGANISER', 'ADMIN')),
    is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);


DROP TABLE IF EXISTS events;
CREATE TABLE events (
    event_id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN ('MOVIE', 'CONCERT')),
    description TEXT,
    poster_url TEXT,
    banner_url TEXT,
    start_date TEXT NOT NULL,
    end_date TEXT,
    duration_minutes INTEGER,
    age_rating TEXT,
    status TEXT NOT NULL DEFAULT 'UPCOMING' CHECK (status IN ('ONGOING','UPCOMING','COMPLETED','CANCELLED')),
    city TEXT NOT NULL,
    region TEXT NOT NULL DEFAULT 'Other',
    venue TEXT,
    base_price REAL NOT NULL DEFAULT 0,
    organiser_id INTEGER,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (organiser_id) REFERENCES users(user_id) ON DELETE SET NULL
);


DROP TABLE IF EXISTS movie_details;
CREATE TABLE movie_details (
    movie_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL UNIQUE,
    genre TEXT,
    director TEXT,
    cast_members TEXT,
    original_language TEXT,
    trailer_url TEXT,
    rating REAL DEFAULT 0,
    total_reviews INTEGER DEFAULT 0,
    FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE
);


DROP TABLE IF EXISTS movie_languages;
CREATE TABLE movie_languages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    language TEXT NOT NULL,
    FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE,
    UNIQUE(event_id, language)
);


DROP TABLE IF EXISTS movie_formats;
CREATE TABLE movie_formats (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    format_name TEXT NOT NULL CHECK (format_name IN ('2D','3D','IMAX 2D','IMAX 3D','4DX','4DX 3D')),
    price REAL NOT NULL,
    FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE,
    UNIQUE(event_id, format_name)
);


DROP TABLE IF EXISTS concert_details;
CREATE TABLE concert_details (
    concert_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL UNIQUE,
    artist TEXT NOT NULL,
    genre TEXT,
    city TEXT,
    venue TEXT,
    FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE
);


DROP TABLE IF EXISTS venues;
CREATE TABLE venues (
    venue_id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    address TEXT,
    city TEXT NOT NULL,
    region TEXT NOT NULL DEFAULT 'Other',
    capacity INTEGER DEFAULT 0,
    venue_type TEXT CHECK (venue_type IN ('CINEMA','CONCERT','AUDITORIUM','STADIUM','OPEN_AIR')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);


DROP TABLE IF EXISTS screens;
CREATE TABLE screens (
    screen_id INTEGER PRIMARY KEY AUTOINCREMENT,
    venue_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    screen_type TEXT CHECK (screen_type IN ('STANDARD','IMAX','IMAX_3D','4DX','AUDITORIUM')),
    total_seats INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (venue_id) REFERENCES venues(venue_id) ON DELETE CASCADE,
    UNIQUE(venue_id, name)
);


DROP TABLE IF EXISTS seats;
CREATE TABLE seats (
    seat_id INTEGER PRIMARY KEY AUTOINCREMENT,
    screen_id INTEGER NOT NULL,
    seat_number TEXT NOT NULL,
    row_label TEXT NOT NULL,
    seat_category TEXT NOT NULL CHECK (seat_category IN ('STANDARD','PREMIUM','VIP','VVIP')),
    price_multiplier REAL NOT NULL DEFAULT 1.0,
    FOREIGN KEY (screen_id) REFERENCES screens(screen_id) ON DELETE CASCADE,
    UNIQUE(screen_id, seat_number)
);


DROP TABLE IF EXISTS shows;
CREATE TABLE shows (
    show_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    venue_id INTEGER NOT NULL,
    screen_id INTEGER,
    show_date TEXT NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT,
    language TEXT,
    format_name TEXT,
    ticket_price REAL NOT NULL,
    status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK (status IN ('AVAILABLE','SOLD_OUT','CANCELLED','COMPLETED')),
    FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE,
    FOREIGN KEY (venue_id) REFERENCES venues(venue_id) ON DELETE CASCADE,
    FOREIGN KEY (screen_id) REFERENCES screens(screen_id) ON DELETE SET NULL
);


DROP TABLE IF EXISTS show_seats;
CREATE TABLE show_seats (
    show_seat_id INTEGER PRIMARY KEY AUTOINCREMENT,
    show_id INTEGER NOT NULL,
    seat_id INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK (status IN ('AVAILABLE','HELD','BOOKED')),
    hold_expires_at TEXT,
    booking_id INTEGER,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (show_id) REFERENCES shows(show_id) ON DELETE CASCADE,
    FOREIGN KEY (seat_id) REFERENCES seats(seat_id) ON DELETE CASCADE,
    UNIQUE(show_id, seat_id)
);


DROP TABLE IF EXISTS seat_holds;
CREATE TABLE seat_holds (
    hold_id INTEGER PRIMARY KEY AUTOINCREMENT,
    show_id INTEGER NOT NULL,
    seat_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    hold_token TEXT NOT NULL UNIQUE,
    expires_at TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','EXPIRED','CONVERTED','CANCELLED')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (show_id) REFERENCES shows(show_id) ON DELETE CASCADE,
    FOREIGN KEY (seat_id) REFERENCES seats(seat_id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS bookings;
CREATE TABLE bookings (
    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
    booking_reference TEXT NOT NULL UNIQUE,
    user_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    subtotal REAL NOT NULL DEFAULT 0,
    convenience_fee REAL NOT NULL DEFAULT 0,
    tax REAL NOT NULL DEFAULT 0,
    discount REAL NOT NULL DEFAULT 0,
    total_amount REAL NOT NULL DEFAULT 0,
    booking_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (booking_status IN ('PENDING','CONFIRMED','CANCELLED','EXPIRED','REFUNDED')),
    qr_code TEXT,
    qr_data TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    confirmed_at TEXT,
    cancelled_at TEXT,
    FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    FOREIGN KEY (show_id) REFERENCES shows(show_id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS booking_seats;
CREATE TABLE booking_seats (
    booking_seat_id INTEGER PRIMARY KEY AUTOINCREMENT,
    booking_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    seat_id INTEGER NOT NULL,
    seat_number TEXT NOT NULL,
    seat_category TEXT NOT NULL,
    price REAL NOT NULL,
    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE,
    FOREIGN KEY (show_id) REFERENCES shows(show_id) ON DELETE CASCADE,
    FOREIGN KEY (seat_id) REFERENCES seats(seat_id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS payments;
CREATE TABLE payments (
    payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    booking_id INTEGER NOT NULL,
    transaction_id TEXT UNIQUE,
    payment_method TEXT CHECK (payment_method IN ('UPI','CARD','NET_BANKING','WALLET','CASH','TEST')),
    amount REAL NOT NULL,
    payment_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (payment_status IN ('PENDING','SUCCESS','FAILED','REFUNDED')),
    paid_at TEXT,
    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS waitlist;
CREATE TABLE waitlist (
    waitlist_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    show_id INTEGER,
    user_id INTEGER NOT NULL,
    seat_category TEXT NOT NULL CHECK (seat_category IN ('STANDARD','PREMIUM','VIP','VVIP')),
    position INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'WAITING' CHECK (status IN ('WAITING','OFFERED','BOOKED','EXPIRED','CANCELLED')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (event_id) REFERENCES events(event_id) ON DELETE CASCADE,
    FOREIGN KEY (show_id) REFERENCES shows(show_id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE
);


DROP TABLE IF EXISTS waitlist_offers;
CREATE TABLE waitlist_offers (
    offer_id INTEGER PRIMARY KEY AUTOINCREMENT,
    waitlist_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    seat_id INTEGER NOT NULL,
    offer_token TEXT NOT NULL UNIQUE,
    expires_at TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','ACCEPTED','EXPIRED','DECLINED')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (waitlist_id) REFERENCES waitlist(waitlist_id) ON DELETE CASCADE,
    FOREIGN KEY (show_id) REFERENCES shows(show_id) ON DELETE CASCADE,
    FOREIGN KEY (seat_id) REFERENCES seats(seat_id) ON DELETE CASCADE
);

DROP TABLE IF EXISTS email_logs;
CREATE TABLE email_logs (
    email_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    booking_id INTEGER,
    email_type TEXT CHECK (email_type IN ('BOOKING_CONFIRMATION','WAITLIST_OFFER','CANCELLATION','PASSWORD_RESET')),
    recipient TEXT NOT NULL,
    subject TEXT,
    status TEXT DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','FAILED')),
    sent_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE SET NULL
);


PRAGMA foreign_keys = ON;
