INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (16, 'Stree 2', 'MOVIE', 'The town of Chanderi is haunted once again by a terrifying headless entity known as Sarkata. Vicky and his loyal gang must unite with Stree to protect the town in this blockbuster horror-comedy.', 'https://upload.wikimedia.org/wikipedia/en/a/a1/Stree_2.jpg', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1400&q=85', '2026-08-15', '2026-09-30', 149, 'UA', 'ONGOING', 'Delhi', 'Delhi NCR', 'PVR IMAX Select Citywalk, Saket', 320, 3, '2026-08-22 07:36:06');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (17, 'Fighter', 'MOVIE', 'Top IAF aviators come together in the face of imminent danger to form the elite Air Dragons unit, embarking on perilous aerial combat missions to defend national airspace.', 'https://image.tmdb.org/t/p/w500/zqFuriKJ6pYDvf72kXNLONnuE8k.jpg', 'https://images.unsplash.com/photo-1517976487541-11b052bc9576?auto=format&fit=crop&w=1400&q=85', '2026-08-20', '2026-09-30', 166, 'UA', 'ONGOING', 'Mumbai', 'Mumbai', 'Mahalaxmi Race Course / IMAX Theatre', 400, 3, '2026-08-22 07:36:06');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (18, 'Bhool Bhulaiyaa 3', 'MOVIE', 'Rooh Baba ventures into the mysterious royal palace of Rakht Ghat in West Bengal, confronting two vengeful spirits who claim to be Manjulika in this supernatural comedy sequel.', 'https://m.media-amazon.com/images/M/MV5BYmIxNzNiYzItNzFlOC00OGQ3LTllMTAtMzQ3ZTM5MmRiYzVlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&w=1400&q=85', '2026-09-01', '2026-10-15', 158, 'UA', 'UPCOMING', 'Noida', 'Delhi NCR', 'PVR INOX Mall of India, Noida', 300, 3, '2026-08-22 07:36:06');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (19, 'Yo Yo Honey Singh - Glory Live 2026', 'CONCERT', 'The pioneer of Indian Hip Hop and Desi Rap, Yo Yo Honey Singh, brings his explosive Glory World Tour to Delhi NCR with an electrifying live band, massive pyro stage, and iconic chart-topping bangers.', 'https://images.filmibeat.com/img/2025/02/mainhoneysingh-1739891293.jpg', 'https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=1400&q=85', '2026-10-24', '2026-10-24', 180, 'All Ages', 'UPCOMING', 'Gurugram', 'Delhi NCR', 'Leisure Valley Ground, Sector 29, Gurugram', 1499, 3, '2026-08-22 07:36:06');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (20, 'Arijit Singh - Soulful Symphony Live', 'CONCERT', 'Experience an enchanting, unforgettable evening with India''s voice of romance, Arijit Singh. A 3-hour mega live orchestral performance featuring Bollywood''s most beloved anthems and soulful ballads.', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?auto=format&fit=crop&w=1400&q=85', '2026-11-08', '2026-11-08', 200, 'All Ages', 'UPCOMING', 'Delhi', 'Delhi NCR', 'Jawaharlal Nehru Stadium, New Delhi', 1999, 3, '2026-08-22 07:36:06');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (21, 'Diljit Dosanjh - Dil-Luminati India Tour', 'CONCERT', 'The global Punjabi superstar Diljit Dosanjh sets the stadium on fire with high-energy Punjabi beats, bhangra grooves, world-class choreography, and sensational stage production.', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&w=1400&q=85', '2026-11-20', '2026-11-20', 180, 'All Ages', 'UPCOMING', 'Delhi', 'Delhi NCR', 'Jawaharlal Nehru Stadium, New Delhi', 2499, 3, '2026-08-22 07:36:07');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (22, 'Karan Aujla - It Was All A Dream Tour', 'CONCERT', 'Geetan Di Machine Karan Aujla live in concert with his international band performing chartbuster hits including Tauba Tauba, Winning Speech, 52 Bars, and Softly.', 'https://images.unsplash.com/photo-1508700115892-45ecd05ae2ad?auto=format&fit=crop&w=1000&q=85', 'https://images.unsplash.com/photo-1540039155733-5bb30b53aa14?auto=format&fit=crop&w=1400&q=85', '2026-12-05', '2026-12-05', 150, 'All Ages', 'UPCOMING', 'Gurugram', 'Delhi NCR', 'Leisure Valley Ground, Sector 29, Gurugram', 1299, 3, '2026-08-22 07:36:07');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (23, 'TOXIC: A Fairy Tale for Grown-ups', 'MOVIE', 'Rocking Star Yash stars in a grand, visually stunning period gangster fairy tale set against the gritty underworld of the 1950s-1970s, directed by National Award winner Geetu Mohandas.', 'https://upload.wikimedia.org/wikipedia/en/0/0b/Toxic-_A_Fairy_Tale_for_Grown-Ups_poster.jpg', 'https://images.unsplash.com/photo-1485846234645-a62644f84728?auto=format&fit=crop&w=1400&q=85', '2026-09-10', '2026-11-15', 172, 'A', 'UPCOMING', 'Bengaluru', 'Bengaluru', 'NICE Grounds / PVR IMAX Orion Mall', 380, 3, '2026-08-22 08:08:30');
INSERT INTO events (event_id, title, event_type, description, poster_url, banner_url, start_date, end_date, duration_minutes, age_rating, status, city, region, venue, base_price, organiser_id, created_at) VALUES (24, 'Mirzapur: The Movie', 'MOVIE', 'Kaleen Bhaiya, Guddu Pandit, and Munna Bhaiya collide on the giant silver screen. The battle for the throne of Purvanchal reaches unprecedented cinematic scale with raw dialogues, intense shootouts, and power politics.', 'https://cdn.district.in/movies-assets/images/cinema/_Poster-ad72d610-7068-11f1-a674-fd16b95428a1.jpg', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=1400&q=85', '2026-09-25', '2026-11-30', 158, 'A', 'UPCOMING', 'Gurugram', 'Delhi NCR', 'PVR INOX Ambience Mall, Gurugram', 350, 3, '2026-08-22 08:08:30');
